def fizzbuzz(n: int) -> list[str]:
    return [
        'FizzBuzz' if i % 3 == 0 and i % 5 == 0
        else 'Fizz' if i % 3 == 0
        else 'Buzz' if i % 5 == 0
        else str(i)
        for i in range(1, n + 1)
    ]

def parsear_duracion(s: str) -> int:
    total_minutos = 0
    for caracter in s:
        if caracter == 'h':
            total_minutos += 60
        elif caracter == 'm':
            total_minutos += 1
    return total_minutos

def es_palindromo(s: str) -> bool:
    s = ''.join(c.lower() for c in s if c.isalnum())
    return s == s[::-1]

def aplanar(lista):
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

def buscar(lista, x):
    izq = 0
    der = len(lista) - 1

    while izq <= der:
        mid = (izq + der) // 2
        if lista[mid] == x:
            return mid
        elif lista[mid] < x:
            izq = mid + 1
        else:
            der = mid - 1

    return -1

def agrupar_por(items, clave):
    resultado = {}
    for item in items:
        valor = item[clave]
        if valor not in resultado:
            resultado[valor] = []
        resultado[valor].append(item)
    return resultado

def contar_palabras(texto: str) -> dict:
    import re
    palabras = re.findall(r'\b\w+\b', texto.lower())
    return {palabra: palabras.count(palabra) for palabra in palabras}

def rotar(lista, n):
    if not lista:
        return []
    n = n % len(lista)
    if n < 0:
        n += len(lista)
    return lista[-n:] + lista[:-n]

def a_romano(n):
    if n < 1 or n > 3999:
        raise ValueError("El número debe estar entre 1 y 3999")

    valores = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    simbolos = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]

    resultado = ""
    for i in range(len(valores)):
        while n >= valores[i]:
            resultado += simbolos[i]
            n -= valores[i]

    return resultado

def mayor_racha(lista: list) -> tuple | None:
    if not lista:
        return None

    mayor_racha = (lista[0], 1)

    for i in range(1, len(lista)):
        if lista[i] == lista[i - 1]:
            mayor_racha = (lista[i], mayor_racha[1] + 1)
        else:
            mayor_racha = (lista[i], 1)

    return mayor_racha

def primos(n):
    if n < 2:
        return []
    primos = [2]
    for i in range(3, n + 1, 2):
        if all(i % j != 0 for j in range(3, int(i**0.5) + 1, 2)):
            primos.append(i)
    return primos

def mcd(a: int, b: int) -> int:
    while b != 0:
        a, b = b, a % b
    return a

def fusionar(intervalos: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """
    Fusiona una lista de intervalos ordenados por inicio.
    Dos intervalos que se tocan en un extremo se fusionan.
    """
    intervalos.sort()
    resultado = [intervalos[0]]

    for inicio, fin in intervalos[1:]:
        if inicio <= resultado[-1][1]:
            resultado[-1] = (resultado[-1][0], max(resultado[-1][1], fin))
        else:
            resultado.append((inicio, fin))

    return resultado

def comprimir(s: str) -> str:
    if len(s) <= 1:
        return s

    comprimido = ""
    i = 0
    while i < len(s):
        contador = 1
        while i + 1 < len(s) and s[i] == s[i + 1]:
            contador += 1
            i += 1
        comprimido += str(contador) + s[i]
        i += 1

    if len(comprimido) < len(s):
        return comprimido
    return s

def balanceado(texto: str) -> bool:
    pila = []
    pares = {')': '(', ']': '[', '}': '{'}

    for caracter in texto:
        if caracter in ('(', '[', '{'):
            pila.append(caracter)
        elif caracter in (')', ']', '}'):
            if not pila or pila[-1] != pares[caracter]:
                return False
            pila.pop()

    return len(pila) == 0

