def dedup(lista):
    seen = set()
    resultado = []
    for elemento in lista:
        if elemento not in seen:
            seen.add(elemento)
            resultado.append(elemento)
    return resultado

def busqueda_binaria(lista: list, x: int) -> int:
    """
    Busca x en una lista ORDENADA usando busqueda binaria.
    Devuelve el indice de x o -1 si no esta.
    """
    izq = 0
    der = len(lista) - 1

    while izq <= der:
        mid = (izq + der) // 2
        if lista[mid] == x:
            return mid
        elif lista[mid] < x:
            izq = mid + 1
        else:
            der = mid - 1

    return -1

def dict_nested(d: dict) -> dict:
    """Convierte un dict de claves con puntos en un dict anidado."""
    result = {}
    for key, value in d.items():
        keys = key.split('.')
        current = result
        for k in keys[:-1]:
            if k not in current:
                current[k] = {}
            current = current[k]
        current[keys[-1]] = value
    return result

