def contar_islas(grid: list[list[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    filas, columnas = len(grid), len(grid[0])
    visited = [[False] * columnas for _ in range(filas)]
    count = 0

    def dfs(r: int, c: int) -> None:
        visited[r][c] = True
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < filas and 0 <= nc < columnas and not visited[nr][nc] and grid[nr][nc] == 1:
                dfs(nr, nc)

    for i in range(filas):
        for j in range(columnas):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                dfs(i, j)

    return count

def distancia(a: str, b: str) -> int:
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])

    return dp[m][n]

def validar_password(p: str) -> bool:
    if len(p) < 8:
        return False
    if not any(c.isupper() for c in p):
        return False
    if not any(c.islower() for c in p):
        return False
    if not any(c.isdigit() for c in p):
        return False
    if not any(not c.isalnum() for c in p):
        return False
    return True

def a_base(n, base):
    if n == 0:
        return '0'
    digits = '0123456789abcdef'
    result = ''
    while n > 0:
        result = digits[n % base] + result
        n //= base
    return result

def interseccion(a: list[int], b: list[int]) -> list[int]:
    resultado = []
    i, j = 0, 0
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            resultado.append(a[i])
            i += 1
            j += 1
        elif a[i] < b[j]:
            i += 1
        else:
            j += 1
    return resultado

from datetime import datetime

def dias_entre(a: str, b: str) -> int:
    fecha_a = datetime.strptime(a, '%Y-%m-%d')
    fecha_b = datetime.strptime(b, '%Y-%m-%d')
    return abs((fecha_b - fecha_a).days)

