def titular(s: str) -> str:
    palabras = s.split()
    resultado = []
    for i, palabra in enumerate(palabras):
        if i == 0:
            resultado.append(palabra.capitalize())
        elif palabra.lower() in ('de', 'del', 'la', 'las', 'el', 'los', 'y'):
            resultado.append(palabra.lower())
        else:
            resultado.append(palabra.capitalize())
    return ' '.join(resultado)

def aplanar_hasta(lista, profundidad):
    if profundidad == 0:
        return lista
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar_hasta(elemento, profundidad - 1))
        else:
            resultado.append(elemento)
    return resultado

def sumar_romanos(a: str, b: str) -> str:
    valores = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    def romano_a_entero(s: str) -> int:
        total = 0
        prev = 0
        for letra in reversed(s):
            valor = valores[letra]
            if valor < prev:
                total -= valor
            else:
                total += valor
            prev = valor
        return total

    def entero_a_romano(n: int) -> str:
        if n == 0:
            return ''
        resultado = ''
        while n > 0:
            if n % 1000 == 0:
                resultado += 'M' * (n // 1000)
                n %= 1000
            elif n % 100 == 0:
                resultado += 'C' * (n // 100)
                n %= 100
            elif n % 10 == 0:
                resultado += 'X' * (n // 10)
                n %= 10
            elif n % 5 == 0:
                resultado += 'V'
                n -= 5
            elif n % 4 == 0:
                resultado += 'IV'
                n -= 4
            elif n % 9 == 0:
                resultado += 'IX'
                n -= 9
            elif n % 10 == 1:
                resultado += 'I'
                n -= 1
            elif n % 10 == 2:
                resultado += 'II'
                n -= 2
            elif n % 10 == 3:
                resultado += 'III'
                n -= 3
            elif n % 10 == 6:
                resultado += 'VI'
                n -= 6
            elif n % 10 == 7:
                resultado += 'VII'
                n -= 7
            elif n % 10 == 8:
                resultado += 'VIII'
                n -= 8
            n -= 1
        return resultado[::-1]

    return entero_a_romano(romano_a_entero(a) + romano_a_entero(b))

def con_reintentos(fn, veces):
    for i in range(veces):
        try:
            return fn()
        except Exception as e:
            if i == veces - 1:
                raise
            continue
